export type UserInfo = BaseUserInfo & {
    /**
     * 当前请求者可否为该账号改名；仅超级管理员且目标不是初始化管理员或系统游客时为true。旧客户端缺省按false处理。
     */
    canRenameUsername?: boolean;
    /**
     * 用户所属角色 ID 列表；后端实现使用 Django Group
     */
    groupIds: Array<number>;
    /**
     * 用户账号是否启用
     */
    isActive: boolean;
    /**
     * 用户通过所属角色继承的平台功能权限列表
     */
    groupPermissions: Array<string>;
    /**
     * 单独授予该用户的平台功能权限列表，不包含用户组继承权限
     */
    directPermissions: Array<string>;
    /**
     * 单独关闭该用户已授予的平台功能权限列表，可用于关闭角色继承权限或单独授予权限
     */
    disabledPermissions: Array<string>;
    /**
     * 角色权限与用户直授权限合并后，扣除用户单独关闭权限的实际生效功能权限列表
     */
    effectivePermissions: Array<string>;
    /**
     * 该用户具备 `core.view_group_operation_logs` 时允许查看日志的目标用户组 ID 列表
     */
    operationLogGroupIds: Array<number>;
};

export type UserCreateRequest = {
    /**
     * 登录用户名
     */
    username: string;
    /**
     * 显示名称
     */
    displayName?: string;
    /**
     * 超级管理员创建时可省略或留空，普通管理员必填；非空邮箱统一转为小写并保证唯一。
     */
    email?: string | '';
    /**
     * 用户所在部门
     */
    department?: string;
    /**
     * 初始所属用户组 ID 列表，必填且至少包含一个非超级管理员用户组
     */
    groupIds: Array<number>;
    /**
     * 是否启用账号，默认 true
     */
    isActive?: boolean;
    /**
     * 仅超级管理员可提交的启用私有项目ID；公开项目由allowPublicProject单独控制。省略时不分配私有项目，重复ID去重。
     */
    projectIds?: Array<number>;
    /**
     * 仅超级管理员可提交，是否允许访问公开项目；关闭时须至少分配一个启用私有项目。普通管理员不得提交，即使为默认值。
     */
    allowPublicProject?: boolean;
};

