/**
 * 甲方确认的业务数据类型编码；vector 表示直接以点、线、面几何图层为主体管理的矢量数据。
 */
export type DataDomainType = 'germplasm' | 'genome' | 'individual' | 'community' | 'population' | 'field_survey' | 'remote_sensing' | 'molecular' | 'vector' | 'other';

/**
 * 数据与空间几何的关系。
 */
export type SpatialClass = 'spatial' | 'non_spatial' | 'spatialized_table' | 'derived_from_spatial';

/**
 * 数据资源工作台分类；spatial 表示具有已解析坐标参考系统的矢量或栅格资源（含坐标表格转换的点图层），non_spatial 表示不含可用空间几何的表格、基因、文档或图片资源。
 */
export type ResourceSpatialClass = 'spatial' | 'non_spatial';

/**
 * 数据记录粒度。
 */
export type DataGranularity = 'region' | 'site' | 'population' | 'individual' | 'plot' | 'observation' | 'sample' | 'molecular_assay' | 'genome_file' | 'raster_scene' | 'raster_product';

/**
 * 数据标准化状态。
 */
export type StandardizationStatus = 'raw' | 'profiled' | 'mapped' | 'spatialized' | 'standardized' | 'published';

export type DataDomainDefinition = {
    code: DataDomainType;
    /**
     * 业务数据类型中文名称。
     */
    name: string;
    spatialClass: SpatialClass;
    /**
     * 数据类型说明。
     */
    description: string;
    /**
     * 推荐使用的 DataResource.dataType 类型。
     */
    recommendedResourceTypes: Array<'vector' | 'raster' | 'gene' | 'table' | 'document' | 'image'>;
    /**
     * 该业务类型涉及的核心数据库实体名称。
     */
    coreEntities: Array<string>;
};

export type DataSchemaLayer = {
    /**
     * 数据库层级名称。
     */
    name: string;
    /**
     * 主要存储位置。
     */
    storage: string;
    /**
     * 层级职责说明。
     */
    description: string;
};

export type DataSchemaEntity = {
    /**
     * 建议模型或表名。
     */
    name: string;
    /**
     * 中文名称。
     */
    label: string;
    /**
     * 关联的业务数据类型。
     */
    domainTypes: Array<DataDomainType>;
    /**
     * 实体职责说明。
     */
    description: string;
    /**
     * 建议关键字段。
     */
    keyFields: Array<string>;
};

export type DataSchemaSummaryResponse = {
    /**
     * 当前目录分类版本为 2026.10。
     */
    taxonomyVersion: string;
    /**
     * 甲方确认数据类型定义。
     */
    domains: Array<DataDomainDefinition>;
    /**
     * 推荐数据库分层。
     */
    layers: Array<DataSchemaLayer>;
    /**
     * 推荐核心实体模型。
     */
    entities: Array<DataSchemaEntity>;
    /**
     * 面向前端目录展示的建议树。
     */
    catalogTree: Array<DataSchemaCatalogNode>;
};

/**
 * 三类根节点为 spatial（地理数据）、non_spatial（非地理数据）和 compute_results（计算结果）。普通上传按坐标解析结果自动归类；计算输出入库统一归入计算结果，资源自身空间属性保持。
 */
export type DataSchemaCatalogNode = {
    /**
     * 目录节点编码。
     */
    code: string;
    /**
     * 目录节点名称。
     */
    name: string;
    /**
     * 可用于资源筛选和分类提交的稳定业务分类编码。
     */
    categoryCode: string;
    /**
     * 是否允许普通上传选择；spatial 和 non_spatial 为 true，compute_results 为 false。
     */
    selectable: boolean;
    /**
     * 分类边界和适用范围说明。
     */
    description: string;
    /**
     * 从一级分类到当前节点的中文路径。
     */
    path: Array<string>;
    /**
     * 节点对应的数据业务类型，分组节点可为 null。
     */
    domainType?: DataDomainType | null;
    /**
     * 节点空间属性；计算结果包含多种类型，compute_results 节点为 null。
     */
    spatialClass?: SpatialClass | null;
    /**
     * 子目录节点。
     */
    children: Array<DataSchemaCatalogNode>;
};

