/**
 * 当前真实任务的地图资源；输入为模拟识别演示，输出只引用本轮实际计算，不引用交付包PNG
 */
export type AgentMultiElementMap = {
    /**
     * 新栅格流程各矿物的修改前后与变更栅格，引用本次计算输出ID，经现有map-preview接口鉴权读取统一配色PNG；不是资源ID
     */
    alterationRasters?: Array<{
        /**
         * 实际类别的稳定标识
         */
        mineral: string;
        /**
         * 实际类别名称
         */
        label?: string;
        /**
         * 命名类别集合中的实际波段，旧单波段流程缺省1
         */
        band?: number;
        /**
         * 修改前识别栅格计算输出ID
         */
        beforeOutputId: number;
        /**
         * 修正后COG计算输出ID
         */
        afterOutputId?: number;
        /**
         * 规则变更编码栅格计算输出ID
         */
        changesOutputId?: number;
    }>;
    /**
     * 当前检查采用的明确上游版本
     */
    before?: {
        /**
         * 岩性输入资源
         */
        lithology?: number;
        /**
         * 构造输入资源
         */
        faults?: number;
    };
    /**
     * 获批计算形成的新版本，未形成时缺省
     */
    after?: {
        /**
         * 本轮修正岩性资源
         */
        lithology?: number;
        /**
         * 本轮修正构造资源；算子1.0.5起为删除获批剔除线的干净图层，全剔除时缺省，不回退原图
         */
        faults?: number;
    };
    /**
     * 真实变化线点面图层，不含未批准建议；算子1.0.5起为修改前几何的修正记录，含实际动作、原/新代号、宿主编号、规则与批准理由
     */
    changes?: Array<number>;
    /**
     * 当前实际检查的疑点及待核查图层
     */
    checks?: Array<number>;
    /**
     * 本次检查实际读取的修改前矿物面图层，历史任务可缺省
     */
    beforeAlterations?: number;
    /**
     * 算子1.0.5起为仅含有效参与项的干净蚀变面图层（feature_id及alt），全剔除时缺省；历史任务为保留原识别信息和处理状态的图层
     */
    alterations?: number;
    /**
     * 同参数下修改前实际重建的交汇点，历史任务未保存时可缺省
     */
    beforeIntersections?: number;
    /**
     * 几何与推测交汇点，inferred字段决定实心或空心
     */
    intersections?: number;
    /**
     * 修正后远景目标的相对置信度热力栅格计算输出ID，按既有map-preview接口鉴权及后端蓝黄红连续渐变渲染；非矿化概率
     */
    prospectHeatmapOutputId?: number;
    /**
     * 远景区算子2.0协议；仅修正后圈区且无A/B分级，beforeProspects必须缺省；无目标时afterProspects也缺省。缺少本标记的历史任务沿用其已保存的前后分级证据。
     */
    prospectProtocol?: 'after_only_v2';
    /**
     * 历史算子1.x的修正前优先核查远景区；2.0不生成、不读取
     */
    beforeProspects?: number;
    /**
     * 修正后优先核查远景区；2.0统一编号P001等且无grade字段，历史1.x保留其A/B证据组合等级
     */
    afterProspects?: number;
};

