export type ResourceDeletePreviewRequest = {
    /**
     * 待核对资源，重复编号只处理一次。
     */
    resourceIds: Array<number>;
};

/**
 * 当前授权资源的引用影响，历史清理需要用户明确确认。
 */
export type ResourceDeletePreviewItem = {
    /**
     * 请求中的资源编号
     */
    resourceId: number;
    /**
     * 可访问资源名称，不可访问时为空
     */
    name: string | null;
    /**
     * 可删除、需确认历史清理、仍受保护或不存在
     */
    status: 'deletable' | 'confirmation_required' | 'blocked' | 'not_found';
    /**
     * 对用户可读的引用影响或保护原因
     */
    detail: string;
    /**
     * 删除将解除的已结束任务或工作流关联数量
     */
    historyReferenceCount: number;
};

/**
 * 删除影响与绑定用户、项目、资源和引用快照的签名确认凭证。
 */
export type ResourceDeletePreviewResponse = {
    /**
     * 按首次请求顺序返回，受保护项确认后仍不删除。
     */
    items: Array<ResourceDeletePreviewItem>;
    /**
     * 10分钟内有效，引用变化后重新预览，不授予新权限
     */
    confirmationToken: string;
};

/**
 * 当前项目待删除资源，不接受文件路径或其他项目资源。
 */
export type ResourceBulkDeleteRequest = {
    /**
     * 1 至 100 个正整数资源编号，重复编号只处理一次。
     */
    resourceIds: Array<number>;
    /**
     * 用户在界面明确确认永久删除。
     */
    confirmed: true;
    /**
     * 用户检查预览并确认清理历史关联后的签名凭证；仅计算结果允许清理已结束计算和科研记录，名称、来源与删除记录保留，运行中依赖继续保护。
     */
    historyConfirmationToken?: string;
};

/**
 * 一项资源的真实删除结果。
 */
export type ResourceBulkDeleteItem = {
    /**
     * 请求中的资源编号。
     */
    resourceId: number;
    /**
     * 可访问资源名称；not_found 时为空。
     */
    name: string | null;
    /**
     * deleted 已删除；blocked 存在引用等保护；not_found 不存在或不可访问；failed 存储或数据库操作失败。
     */
    status: 'deleted' | 'blocked' | 'not_found' | 'failed';
    /**
     * 用户可读的删除范围或拒绝原因，不返回服务器路径。
     */
    detail: string;
};

/**
 * 部分成功的逐项结果及汇总。
 */
export type ResourceBulkDeleteResponse = {
    /**
     * 按请求首次出现顺序返回每项结果。
     */
    items: Array<ResourceBulkDeleteItem>;
    /**
     * 确实已删除的资源编号，供刷新目录和清理选中项。
     */
    deletedIds: Array<number>;
    /**
     * 成功删除项数。
     */
    deletedCount: number;
    /**
     * 未删除项数，包含 blocked、not_found 和 failed。
     */
    failedCount: number;
};

export type DataResource = {
    /**
     * 数据资源 ID
     */
    id: number;
    /**
     * 数据资源名称
     */
    name: string;
    /**
     * 数据资源编码
     */
    code: string;
    /**
     * 数据资源类型
     */
    dataType: 'vector' | 'raster' | 'gene' | 'table' | 'document' | 'image';
    spatialClass: ResourceSpatialClass;
    /**
     * 平台确认的业务数据类型；历史资源或尚未归类资源为 null
     */
    domainType: DataDomainType | null;
    /**
     * 数据分类，未分类时为 null
     */
    category: DictionaryItem | null;
    /**
     * 从地理数据、非地理数据或计算结果根节点到资源分类的完整路径；待归类时为空数组
     */
    categoryPath: Array<DataCategoryPathItem>;
    classificationStatus: ClassificationStatus;
    /**
     * 后端确认当前已实现的可用展示视图
     */
    availableViews: Array<ResourceView>;
    defaultView: ResourceView;
    /**
     * 数据来源
     */
    source: string;
    /**
     * 数据提供单位
     */
    provider: string;
    /**
     * 数据日期
     */
    dataDate: string | null;
    /**
     * 空间范围文本
     */
    spatialExtent: string;
    /**
     * 坐标系统描述
     */
    coordinateSystem: string;
    /**
     * 文件格式
     */
    fileFormat: string;
    /**
     * 资源描述
     */
    description: string;
    /**
     * 数据质量说明
     */
    qualityNote: string;
    /**
     * 数据大小，单位字节；未知时为 0
     */
    sizeBytes: number;
    /**
     * 数据条目数；未知时为 0
     */
    itemCount: number;
    /**
     * 数据资源状态
     */
    status: 'active' | 'inactive';
    /**
     * 是否支持矢量属性和空间查询
     */
    isQueryable: boolean;
    /**
     * 是否支持地图渲染
     */
    isRenderable: boolean;
    /**
     * 最后更新时间
     */
    updatedAt: string;
    /**
     * 单个业务项目标签 ID，缺省为公开项目 1。all 汇总已取消，业务接口读写均仅接受一个具体项目，传 all 返回 400。与地图工程 projectId 不同；平台管理接口独立执行管理权限检查。
     */
    projectTagId?: number;
};

