    code: string;
    /**
     * 调度说明
     */
    message: string;
    /**
     * 涉及输入
     */
    inputs: Array<string>;
    /**
     * 涉及参数
     */
    parameters: Array<string>;
    /**
     * 补救类别
     */
    remedy: 'adjust_parameters' | 'convert_input' | 'complete_mapping' | 'replace_data' | 'human_review' | 'unrecoverable';
    /**
     * 有界补充诊断，不包含秘密或主机路径
     */
